public class AuthenticationFilter implements Filter {
    @Override
    public void doFilter(ServletRequest servletRequest,
                         ServletResponse servletResponse,
                         FilterChain filterChain) throws IOException, ServletException {
        HttpServletRequest req = (HttpServletRequest) servletRequest;
        HttpServletResponse res = (HttpServletResponse) servletResponse;
        String token = req.getHeader("token");
        if (token == null || !token.equals("12345")) {
            res.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
            res.setContentType("application/json");
            res.getWriter().write("{\"message\" : \"Authentication is required\"}");
            return;
        }
        filterChain.doFilter(servletRequest, servletResponse);
    }
}

@Component
public class AuditFilter implements Filter {
    @Override
    public void doFilter(ServletRequest request, ServletResponse response,
                         FilterChain chain) throws IOException, ServletException {
        ContentCachingResponseWrapper wrapped =
                new ContentCachingResponseWrapper((HttpServletResponse) response);
        chain.doFilter(request, wrapped);
        byte[] body = wrapped.getContentAsByteArray();
        System.out.println("Response size: " + body.length);
    }
}

public class DummyFilter implements Filter {
    @Override
    public void doFilter(ServletRequest servletRequest,
                         ServletResponse servletResponse,
                         FilterChain filterChain) throws IOException, ServletException {
        HttpServletRequest req = (HttpServletRequest) servletRequest;
        String uri = req.getRequestURI();

        if (!uri.startsWith("/api/")) {
            filterChain.doFilter(servletRequest, servletResponse);
        }

        System.out.println("Dummy filter called");
        filterChain.doFilter(servletRequest, servletResponse);
    }
}

@Bean
public FilterRegistrationBean<DummyFilter> getDummyFilterBean() {
    FilterRegistrationBean<DummyFilter> registrationBean = new FilterRegistrationBean<>();
    registrationBean.setFilter(new DummyFilter());
    registrationBean.addUrlPatterns("/api/*, /admin/*");
    return registrationBean;
}
